a=read('assumptions.csv')
for r in a:
 if r['assumption_id'] in notes:
  r['parameter'],r['rationale'],r['range_or_unknown'],r['sensitivity_and_decision_effect'],r['how_to_refine']=notes[r['assumption_id']]
table('assumptions.csv',a)
# В S1 сезонные частоты должны совпадать с правилами календаря малого сравнения.
p=load('programme_candidates.json')
s1=next(r for r in p['programmes'] if r['programme_id']=='PEE-S1')
if not any('зима' in f.get('season','') for f in s1['flights']):
 for d,freq in [('LED',2),('NOZ',1),('KJA',1)]:
  s1['flights'].append(dict(airport_pair=['SVX',d],roundtrips_per_week=freq,season='зима и межсезонье',rotation='SVX>'+d+'>SVX',action='ADD_FREQUENCY_IF_KEEP_EXISTS_ELSE_NEW_CONDITIONAL',source_status='SCENARIO_DESIGN',capacity_status='NOT_ADMITTED'))
for r in p['programmes']:
 if r['programme_id']=='PEE-R1':r['assumption_ids']=list(dict.fromkeys(r['assumption_ids']+['A-PEE-DAILY_CAP']))
save('programme_candidates.json',p)
