# Manifest не включает собственный hash во избежание рекурсии.
files=[]
for f in sorted(B.rglob('*')):
 if f.is_file() and f.name!='output_manifest.json' and '__pycache__' not in f.parts:
  files.append(dict(path=str(f.relative_to(B)),size_bytes=f.stat().st_size,sha256=hashlib.sha256(f.read_bytes()).hexdigest()))
save('output_manifest.json',dict(package='PEE/research_v1',status='STAGE_A_COMPLETE_STAGE_B_NOT_RUN',created_at=datetime.datetime.now(datetime.timezone.utc).isoformat(),scope='Только назначенный каталог; без Git mutations, детей, внешних сообщений/сервисов, бронирований и публичного Site.',file_count=len(files),files=files,self_hash_policy='Файл output_manifest.json исключён из списка hashes; его SHA256 передаётся координатору отдельно.',reproduction=['python3 collect_local.py — новый HTTP-срез, может изменить источники; для повторения frozen пакета НЕ запускать.','python3 build_package.py — читает exact Git objects и уже сохранённые sources.','python3 enrich_package.py — читательские формулировки и scoped resource correction.','python3 final_findings.py — локальный clock issue, selection audit, точечные evidence и узкие срезы драйверов.','python3 seal_package.py; python3 validate.py — приёмка и новый manifest.']))
print('Sealed',len(files),'files;',sum(r['size_bytes'] for r in files),'bytes')
